import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";

const OrderTrackingPopup = ({ isOpen, onClose, orderId, backendUrl, cart, totalPrice }) => {
    const [timeLeft, setTimeLeft] = useState(120); // 2 minutes = 120 seconds
    const [orderStatus, setOrderStatus] = useState({
        status: "pending",
        message: "Initializing payment...",
        orderData: null,
    });
    const [isPolling, setIsPolling] = useState(true);
    const [refreshCount, setRefreshCount] = useState(0);
    const [maxRefreshes] = useState(25);
    const [showCancelConfirmation, setShowCancelConfirmation] = useState(false);
    const navigate = useNavigate();

    // Store interval refs to clear them when needed
    const statusIntervalRef = useRef(null);
    const timerIntervalRef = useRef(null);

    // Check order status via backend
    const checkOrderStatus = async () => {
        try {
            const response = await fetch(`${backendUrl}/api/verify-payment-db`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ txnid: orderId })
            });

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            const data = await response.json();

            if (data.success && data.found && data.transaction) {
                const transaction = data.transaction;

                if (transaction.status === "success" || transaction.status === "SUCCESS") {
                    setIsPolling(false);
                    setTimeout(() => {
                        onClose();
                        navigate("/thank-you", {
                            state: {
                                app: "UPI",
                                paymentId: transaction.mihpayid,
                                txnid: transaction.txnid,
                                amount: transaction.amount,
                                utr: transaction.bank_ref_no
                            }
                        });
                    }, 1500);
                    return {
                        status: "completed",
                        message: "Payment successful!",
                        orderData: transaction,
                    };
                } else if (["failed", "Failed", "FAILED", "failure"].includes(transaction.status)) {
                    setIsPolling(false);
                    setTimeout(() => {
                        onClose();
                        navigate("/payment-failed", {
                            state: {
                                cart: cart,
                                totalPrice: totalPrice,
                                error: transaction.error_message || 'Payment failed'
                            }
                        });
                    }, 1500);
                    return {
                        status: "failed",
                        message: "Payment failed. Please try again.",
                        orderData: transaction,
                    };
                } else {
                    return {
                        status: "processing",
                        message: "Payment in progress...",
                        orderData: transaction,
                    };
                }
            } else {
                return {
                    status: "processing",
                    message: "Checking payment status...",
                    orderData: null,
                };
            }
        } catch (error) {
            console.error("Order status check failed:", error);
            return {
                status: "processing",
                message: "Checking payment status...",
                orderData: null,
            };
        }
    };

    // Reset state when popup is opened with new orderId
    useEffect(() => {
        if (isOpen && orderId) {
            // Clear any existing intervals
            if (statusIntervalRef.current) {
                clearInterval(statusIntervalRef.current);
                statusIntervalRef.current = null;
            }
            if (timerIntervalRef.current) {
                clearInterval(timerIntervalRef.current);
                timerIntervalRef.current = null;
            }

            // Reset all state
            setTimeLeft(120);
            setOrderStatus({
                status: "pending",
                message: "Initializing payment...",
                orderData: null,
            });
            setIsPolling(true);
            setRefreshCount(0);
        }
    }, [isOpen, orderId]);

    // Timer and polling effect
    useEffect(() => {
        if (!isOpen || !orderId || !isPolling || timeLeft <= 0) return;

        // Initial status check
        checkOrderStatus().then((status) => {
            setOrderStatus(status);
        });

        // Set up polling interval (every 3 seconds)
        statusIntervalRef.current = setInterval(async () => {
            if (!isPolling) {
                if (statusIntervalRef.current) {
                    clearInterval(statusIntervalRef.current);
                    statusIntervalRef.current = null;
                }
                return;
            }

            const status = await checkOrderStatus();
            setOrderStatus(status);
        }, 3000);

        // Set up countdown timer
        timerIntervalRef.current = setInterval(() => {
            setTimeLeft((prev) => {
                if (prev <= 1) {
                    if (statusIntervalRef.current) {
                        clearInterval(statusIntervalRef.current);
                        statusIntervalRef.current = null;
                    }
                    if (timerIntervalRef.current) {
                        clearInterval(timerIntervalRef.current);
                        timerIntervalRef.current = null;
                    }
                    setIsPolling(false);
                    setTimeout(() => {
                        onClose();
                        navigate("/payment-failed", {
                            state: {
                                cart: cart,
                                totalPrice: totalPrice,
                                error: 'Payment timeout - please try again'
                            }
                        });
                    }, 1500);
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);

        return () => {
            if (statusIntervalRef.current) {
                clearInterval(statusIntervalRef.current);
                statusIntervalRef.current = null;
            }
            if (timerIntervalRef.current) {
                clearInterval(timerIntervalRef.current);
                timerIntervalRef.current = null;
            }
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isOpen, orderId, timeLeft, isPolling]);

    const formatTime = (seconds) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins}:${secs.toString().padStart(2, "0")}`;
    };

    const getStatusStep = (status) => {
        const steps = {
            pending: 0,
            processing: 1,
            verifying: 2,
            completed: 3,
            failed: 0,
        };
        return steps[status] ?? 0;
    };

    const handleManualRefresh = () => {
        if (refreshCount >= maxRefreshes || !isPolling) return;

        setRefreshCount(prev => prev + 1);
        checkOrderStatus().then((status) => {
            setOrderStatus(status);
        });
    };

    const handleCancelClick = () => {
        setShowCancelConfirmation(true);
    };

    const handleConfirmCancel = () => {
        setShowCancelConfirmation(false);
        setIsPolling(false);

        if (statusIntervalRef.current) {
            clearInterval(statusIntervalRef.current);
            statusIntervalRef.current = null;
        }
        if (timerIntervalRef.current) {
            clearInterval(timerIntervalRef.current);
            timerIntervalRef.current = null;
        }

        setTimeLeft(120);
        setOrderStatus({
            status: "pending",
            message: "Initializing payment...",
            orderData: null,
        });
        setRefreshCount(0);
        onClose();
    };

    if (!isOpen) return null;

    const styles = {
        overlay: {
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.75)',
            backdropFilter: 'blur(8px)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '20px',
            zIndex: 9999,
            animation: 'fadeIn 0.3s ease-out',
        },
        popup: {
            backgroundColor: '#ffffff',
            borderRadius: '24px',
            boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)',
            padding: '0',
            maxWidth: '400px',
            width: '100%',
            position: 'relative',
            overflow: 'hidden',
            fontFamily: "'Inter', sans-serif",
        },
        header: {
            background: 'linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%)',
            padding: '24px 24px 32px',
            borderBottom: '1px solid #e2e8f0',
            textAlign: 'center',
        },
        content: {
            padding: '24px',
        },
        spinnerContainer: {
            position: 'relative',
            width: '80px',
            height: '80px',
            margin: '0 auto 16px',
        },
        spinner: {
            animation: 'spin 1s linear infinite',
            borderRadius: '50%',
            height: '100%',
            width: '100%',
            border: '3px solid transparent',
            borderTopColor: '#3b82f6',
            borderRightColor: '#3b82f6',
            opacity: 0.8,
        },
        spinnerBg: {
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            border: '3px solid #e2e8f0',
            borderRadius: '50%',
        },
        title: {
            fontSize: '22px',
            fontWeight: '800',
            color: '#0f172a',
            marginBottom: '4px',
            letterSpacing: '-0.025em',
        },
        orderId: {
            color: '#64748b',
            fontSize: '13px',
            fontWeight: '500',
            background: '#ffffff',
            padding: '4px 12px',
            borderRadius: '9999px',
            display: 'inline-flex',
            alignItems: 'center',
            gap: '6px',
            border: '1px solid #e2e8f0',
            marginTop: '8px',
        },
        orderIdLabel: {
            color: '#94a3b8',
            fontSize: '12px',
            textTransform: 'uppercase',
            letterSpacing: '0.05em',
            fontWeight: '600',
        },
        orderIdValue: {
            fontFamily: "'JetBrains Mono', monospace",
            color: '#334155',
            fontWeight: '700',
        },
        statusBox: {
            marginTop: '-20px', // Pull up into header
            marginBottom: '24px',
            padding: '16px',
            backgroundColor: '#ffffff',
            borderRadius: '16px',
            boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03)',
            border: '1px solid #f1f5f9',
            textAlign: 'center',
            position: 'relative',
            zIndex: 10,
            marginLeft: '12px',
            marginRight: '12px',
        },
        statusMessage: {
            fontSize: '15px',
            color: '#3b82f6',
            fontWeight: '700',
            marginBottom: '4px',
        },
        amountText: {
            fontSize: '20px', // Larger amount
            fontWeight: '800',
            color: '#0f172a',
            letterSpacing: '-0.025em',
        },
        monitorSection: {
            marginBottom: '24px',
        },
        monitorHeader: {
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginBottom: '8px',
            fontSize: '12px',
            fontWeight: '600',
            color: '#64748b',
        },
        liveIndicator: {
            display: 'flex',
            alignItems: 'center',
            gap: '6px',
            padding: '2px 8px',
            borderRadius: '999px',
            backgroundColor: isPolling ? 'rgba(16, 185, 129, 0.1)' : 'rgba(100, 116, 139, 0.1)',
            color: isPolling ? '#10b981' : '#64748b',
        },
        progressBar: {
            width: '100%',
            backgroundColor: '#f1f5f9',
            borderRadius: '999px',
            height: '6px',
            overflow: 'hidden',
        },
        progressFill: (percent, color = '#3b82f6') => ({
            height: '100%',
            borderRadius: '999px',
            backgroundColor: color,
            width: `${percent}%`,
            transition: 'width 0.5s cubic-bezier(0.4, 0, 0.2, 1)',
        }),
        stepsContainer: {
            display: 'flex',
            justifyContent: 'space-between',
            marginBottom: '32px',
            position: 'relative',
        },
        stepLine: {
            position: 'absolute',
            top: '12px',
            left: '20px',
            right: '20px',
            height: '2px',
            backgroundColor: '#e2e8f0',
            zIndex: 0,
        },
        step: (isActive, isCompleted) => ({
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            position: 'relative',
            zIndex: 1,
            flex: 1,
        }),
        stepDot: (isActive, isCompleted) => ({
            width: '26px',
            height: '26px',
            borderRadius: '50%',
            backgroundColor: isCompleted ? '#3b82f6' : (isActive ? '#ffffff' : '#f1f5f9'),
            border: `2px solid ${isCompleted || isActive ? '#3b82f6' : '#e2e8f0'}`,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
            marginBottom: '8px',
            color: isCompleted ? '#ffffff' : '#3b82f6',
            fontSize: '12px',
        }),
        stepLabel: (isActive, isCompleted) => ({
            fontSize: '11px',
            fontWeight: isActive || isCompleted ? '700' : '500',
            color: isActive || isCompleted ? '#334155' : '#94a3b8',
            transition: 'color 0.3s',
        }),
        timerSection: {
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            padding: '16px',
            backgroundColor: '#f8fafc',
            borderRadius: '16px',
            marginBottom: '24px',
        },
        timerLabel: {
            fontSize: '12px',
            fontWeight: '600',
            color: '#64748b',
            marginBottom: '4px',
            textTransform: 'uppercase',
            letterSpacing: '0.05em',
        },
        timerValue: (isLow) => ({
            fontFamily: "'JetBrains Mono', monospace",
            fontSize: '28px',
            fontWeight: '700',
            color: isLow ? '#ef4444' : '#3b82f6',
            letterSpacing: '-0.05em',
            lineHeight: '1',
        }),
        actions: {
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gap: '12px',
        },
        btn: {
            padding: '12px',
            borderRadius: '12px',
            border: 'none',
            fontSize: '14px',
            fontWeight: '600',
            cursor: 'pointer',
            transition: 'all 0.2s',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '8px',
        },
        refreshBtn: (disabled) => ({
            backgroundColor: disabled ? '#f1f5f9' : '#3b82f6',
            color: disabled ? '#94a3b8' : '#ffffff',
            cursor: disabled ? 'not-allowed' : 'pointer',
            boxShadow: disabled ? 'none' : '0 4px 6px -1px rgba(59, 130, 246, 0.2)',
        }),
        cancelBtn: {
            backgroundColor: '#ffffff',
            color: '#64748b',
            border: '1px solid #e2e8f0',
        },
        // Confirmation Overlay styles
        confirmOverlay: {
            position: 'absolute',
            inset: 0,
            backgroundColor: 'rgba(255, 255, 255, 0.95)',
            backdropFilter: 'blur(4px)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '24px',
            zIndex: 20,
            borderRadius: '24px',
            animation: 'fadeIn 0.2s ease-out',
        },
        confirmBox: {
            width: '100%',
            textAlign: 'center',
        },
        confirmIcon: {
            width: '48px',
            height: '48px',
            borderRadius: '50%',
            backgroundColor: '#fee2e2',
            color: '#ef4444',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            margin: '0 auto 16px',
        },
        confirmTitle: {
            fontSize: '18px',
            fontWeight: '700',
            color: '#1e293b',
            marginBottom: '8px',
        },
        confirmText: {
            color: '#64748b',
            marginBottom: '24px',
            fontSize: '14px',
            lineHeight: '1.5',
        },
        confirmActions: {
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gap: '12px',
        },
        keepBtn: {
            padding: '12px',
            borderRadius: '12px',
            border: '1px solid #e2e8f0',
            backgroundColor: '#ffffff',
            color: '#64748b',
            fontWeight: '600',
            fontSize: '14px',
            cursor: 'pointer',
        },
        yesBtn: {
            padding: '12px',
            borderRadius: '12px',
            border: 'none',
            backgroundColor: '#ef4444',
            color: '#ffffff',
            fontWeight: '600',
            fontSize: '14px',
            cursor: 'pointer',
            boxShadow: '0 4px 6px -1px rgba(239, 68, 68, 0.2)',
        },
    };

    return (
        <div style={styles.overlay}>
            <div style={styles.popup}>
                <div style={styles.header}>
                    <div style={styles.spinnerContainer}>
                        <div style={styles.spinnerBg}></div>
                        <div style={styles.spinner}></div>
                    </div>
                    <h1 style={styles.title}>Processing Payment</h1>
                    <div style={styles.orderId}>
                        <span style={styles.orderIdLabel}>Order ID</span>
                        <span style={styles.orderIdValue}>
                            {orderId ? String(orderId).replace(/payin_?/gi, '') : ''}
                        </span>
                    </div>
                </div>

                <div style={styles.statusBox}>
                    <p style={styles.statusMessage}>{orderStatus.message}</p>
                    {orderStatus.orderData && (
                        <p style={styles.amountText}>₹{orderStatus.orderData.amount}</p>
                    )}
                </div>

                <div style={styles.content}>
                    {/* Steps */}
                    <div style={styles.stepsContainer}>
                        <div style={styles.stepLine}></div>
                        {["Pending", "Processing", "Verifying", "Completed"].map((label, i) => {
                            const stepIndex = getStatusStep(orderStatus.status);
                            const isActive = i === stepIndex;
                            const isCompleted = i < stepIndex;

                            return (
                                <div key={label} style={styles.step(isActive, isCompleted)}>
                                    <div style={styles.stepDot(isActive, isCompleted)}>
                                        {isCompleted ? (
                                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                                                <polyline points="20 6 9 17 4 12"></polyline>
                                            </svg>
                                        ) : (
                                            <div style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: isActive ? '#3b82f6' : 'transparent' }} />
                                        )}
                                    </div>
                                    <span style={styles.stepLabel(isActive, isCompleted)}>{label}</span>
                                </div>
                            );
                        })}
                    </div>

                    {/* Timer */}
                    <div style={styles.timerSection}>
                        <span style={styles.timerLabel}>Time Remaining</span>
                        <span style={styles.timerValue(timeLeft <= 15)}>{formatTime(timeLeft)}</span>
                    </div>

                    {/* Monitor Status */}
                    <div style={styles.monitorSection}>
                        <div style={styles.monitorHeader}>
                            <span>Status Check {refreshCount}/{maxRefreshes}</span>
                            <div style={styles.liveIndicator}>
                                <div style={{
                                    width: '6px',
                                    height: '6px',
                                    borderRadius: '50%',
                                    backgroundColor: isPolling ? '#10b981' : '#64748b',
                                    animation: isPolling ? 'pulse 2s infinite' : 'none'
                                }} />
                                <span>{isPolling ? 'Live' : 'Paused'}</span>
                            </div>
                        </div>
                        <div style={styles.progressBar}>
                            <div style={styles.progressFill((refreshCount / maxRefreshes) * 100)} />
                        </div>
                        <div style={{ ...styles.progressBar, marginTop: '8px' }}>
                            <div style={styles.progressFill(((120 - timeLeft) / 120) * 100, timeLeft <= 15 ? '#ef4444' : '#3b82f6')} />
                        </div>
                    </div>

                    {/* Actions */}
                    <div style={styles.actions}>
                        <button
                            onClick={handleManualRefresh}
                            disabled={!isPolling || refreshCount >= maxRefreshes}
                            style={{ ...styles.btn, ...styles.refreshBtn(!isPolling || refreshCount >= maxRefreshes) }}
                        >
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                <path d="M23 4v6h-6"></path>
                                <path d="M1 20v-6h6"></path>
                                <path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"></path>
                            </svg>
                            <span>{refreshCount >= maxRefreshes ? 'Max Reached' : 'Check Status'}</span>
                        </button>
                        <button onClick={handleCancelClick} style={{ ...styles.btn, ...styles.cancelBtn }}>
                            Cancel
                        </button>
                    </div>
                </div>

                {/* Cancel Confirmation Overlay */}
                {showCancelConfirmation && (
                    <div style={styles.confirmOverlay}>
                        <div style={styles.confirmBox}>
                            <div style={styles.confirmIcon}>
                                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                    <circle cx="12" cy="12" r="10"></circle>
                                    <line x1="15" y1="9" x2="9" y2="15"></line>
                                    <line x1="9" y1="9" x2="15" y2="15"></line>
                                </svg>
                            </div>
                            <h3 style={styles.confirmTitle}>Stop Tracking?</h3>
                            <p style={styles.confirmText}>
                                The payment might still complete in the background. Are you sure?
                            </p>
                            <div style={styles.confirmActions}>
                                <button onClick={() => setShowCancelConfirmation(false)} style={styles.keepBtn}>
                                    Keep Waiting
                                </button>
                                <button onClick={handleConfirmCancel} style={styles.yesBtn}>
                                    Yes, Stop
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                <style>{`
                    @keyframes spin {
                        0% { transform: rotate(0deg); }
                        100% { transform: rotate(360deg); }
                    }
                    @keyframes pulse {
                        0% { opacity: 0.5; transform: scale(0.95); }
                        50% { opacity: 1; transform: scale(1.05); }
                        100% { opacity: 0.5; transform: scale(0.95); }
                    }
                    @keyframes fadeIn {
                        from { opacity: 0; transform: scale(0.95); }
                        to { opacity: 1; transform: scale(1); }
                    }
                `}</style>
            </div>
        </div>
    );
};

export default OrderTrackingPopup;
