import React, { useEffect, useState } from "react";
import { fetchWebControllerData } from "../../utils/dataLoader";
import { useNavigate, useLocation } from "react-router-dom";
import { resolvePath } from "../../utils";

function Thankyou() {
  const navigate = useNavigate();
  const location = useLocation();
  const [logo, setLogo] = useState(resolvePath("/img/flipkart-logo.webp"));
  const [status, setStatus] = useState("processing"); // processing, success, failed

  // Payment details passed from Payment.js
  const { app, paymentId, txnid, utr } = location.state || {};

  useEffect(() => {
    const fetchConfig = async () => {
      try {
        const data = await fetchWebControllerData();
        if (data.thankyouLogo) setLogo(resolvePath(data.thankyouLogo));
      } catch (err) {
        console.error("Error loading JSON config:", err);
      }
    };
    fetchConfig();
  }, []);

  useEffect(() => {
    // Razorpay and UPI (PayU) show success immediately
    if (app === "Razorpay" || app === "UPI") {
      setStatus("success");
    } else {
      // Timer based status for other UPI methods
      const timer = setTimeout(() => {
        setStatus("success");
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [app, paymentId]);


  if (status === "processing") {
    return (
      <div style={{
        textAlign: "center", padding: "60px 20px", display: "flex", flexDirection: "column",
        alignItems: "center", justifyContent: "center", height: "100vh", backgroundColor: "#f9fafb"
      }}>
        <img src={logo} alt="Logo" width="100" style={{ marginBottom: '20px' }} />
        <div className="spinner" style={{
          border: "4px solid #f3f3f3", borderTop: "4px solid #3498db", borderRadius: "50%",
          width: "40px", height: "40px", animation: "spin 1s linear infinite", marginBottom: '20px'
        }}></div>
        <h2 style={{ color: "#333" }}>Processing Payment...</h2>
        <p>Please wait while we confirm your payment.</p>
        <style>{`
                @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
            `}</style>
      </div>
    );
  }

  return (
    <div
      style={{
        textAlign: "center",
        padding: "60px 20px",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        height: "100vh",
        backgroundColor: "#f9fafb"
      }}
    >
      <img src={logo} alt="Success" width="120" />
      <h2 style={{ marginTop: "20px", color: "#16a34a" }}>
        Payment Successful!
      </h2>
      <p style={{ color: "#555", marginTop: "8px" }}>
        Your order has been placed successfully.
      </p>
      {/* Razorpay transaction ID */}
      {app === "Razorpay" && paymentId && (
        <p style={{ fontSize: '12px', color: '#888', marginTop: '5px' }}>Transaction ID: {paymentId}</p>
      )}
      {/* UPI transaction details */}
      {app === "UPI" && (
        <div style={{ marginTop: '10px', fontSize: '12px', color: '#888' }}>
          {paymentId && <p>Transaction ID: {paymentId}</p>}
          {txnid && <p>Order ID: {txnid}</p>}
          {utr && <p>UTR: {utr}</p>}
        </div>
      )}
      <button
        onClick={() => navigate("/")}
        style={{
          marginTop: "25px",
          padding: "10px 20px",
          background: "#2563eb",
          color: "#fff",
          border: "none",
          borderRadius: "8px",
          cursor: "pointer",
          fontWeight: "500"
        }}
      >
        Continue Shopping
      </button>
    </div>
  );
}

export default Thankyou;
