import React from "react";
import { Link, useNavigate, useLocation } from "react-router-dom";

const PaymentFailed = () => {
    const navigate = useNavigate();
    const location = useLocation();

    // Retrieve state passed from Payment.js
    const { cart, totalPrice, error } = location.state || {};

    const handleRetry = () => {
        navigate("/payment", {
            state: {
                cart: cart,
                totalPrice: totalPrice
            }
        });
    };

    return (
        <div style={{ textAlign: "center", padding: "50px" }}>
            <h2 style={{ color: "red" }}>Payment Failed!</h2>
            <p>Something went wrong with your payment.</p>
            {error && <p style={{ color: "gray", fontSize: "14px" }}>Reason: {error}</p>}
            <p>Please try again.</p>

            <button
                onClick={handleRetry}
                style={{
                    padding: "10px 20px",
                    background: "#2563eb",
                    color: "#fff",
                    border: "none",
                    marginTop: "20px",
                    cursor: "pointer",
                    borderRadius: "5px",
                    fontSize: "16px"
                }}
            >
                Pay Again
            </button>
            <br />
            <Link to="/" style={{ display: "block", marginTop: "15px", textDecoration: "none", color: "#555" }}>
                Go to Home
            </Link>
        </div>
    );
};

export default PaymentFailed;
