import React, { useEffect } from "react";
import { Navigate, Outlet, useLocation, useNavigate } from "react-router-dom";

const ProtectedRoute = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const queryParams = new URLSearchParams(location.search);
  
  const hasSecretKey = queryParams.get("access") === "granted";
  
  useEffect(() => {
    if (hasSecretKey) {
      // 1. Session set karein
      sessionStorage.setItem("allowSite", "true");
      
      // 2. URL se "?access=granted" ko hata dein taaki copy na ho sake
      navigate(location.pathname, { replace: true });
    }
  }, [hasSecretKey, navigate, location.pathname]);

  const isAllowed = sessionStorage.getItem("allowSite") === "true";

  if (!isAllowed) {
    return <Navigate to="/404" replace />;
  }

  return <Outlet />;
};

export default ProtectedRoute;








