import { resolvePath } from "../utils";

export const fetchWithCacheBuster = async (url) => {
    const finalUrl = resolvePath(url);
    const separator = finalUrl.includes("?") ? "&" : "?";
    const cacheBuster = `${separator}t=${new Date().getTime()}`;
    const response = await fetch(`${finalUrl}${cacheBuster}`);
    if (!response.ok) {
        throw new Error(`Failed to fetch ${url}: ${response.statusText}`);
    }
    return response.json();
};

export const fetchWebControllerData = () => {
    return fetchWithCacheBuster("/webcontrollerdata.json");
};

export const fetchProductData = () => {
    return fetchWithCacheBuster("/product-data.json");
};
