import React, { useState, useEffect } from "react";
import { fetchWebControllerData } from "../../utils/dataLoader";
import { useLocation, useNavigate } from "react-router-dom";
import { resolvePath } from "../../utils";
import OrderTrackingPopup from "./OrderTrackingPopup";

const INITIAL_TIME = 366;

const Payment = () => {
  const location = useLocation();
  const navigate = useNavigate();

  const [upiOptions, setUpiOptions] = useState([]);
  const [selectedOption, setSelectedOption] = useState("");
  const [timeLeft, setTimeLeft] = useState(INITIAL_TIME);
  const [razorpayConfig, setRazorpayConfig] = useState(null);
  const [phonepeMode, setPhonepeMode] = useState(1);

  // PayU state
  const [payuConfig, setPayuConfig] = useState(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showOrderTracking, setShowOrderTracking] = useState(false);
  const [currentOrderId, setCurrentOrderId] = useState("");

  // Receive cart array and totalPrice from Summary.js
  const cart = location.state?.cart || [];
  const totalPrice = location.state?.totalPrice || 0;
  const protectPromiseFee = 19;

  // PayU UPI options (for radio buttons)
  const payuUpiOptions = [
    { id: 'gpay', name: 'Google Pay', icon: resolvePath("/img/gpay.jpg") },
    { id: 'phonepe', name: 'PhonePe', icon: resolvePath("/img/phone.webp") },
    { id: 'paytm', name: 'Paytm', icon: resolvePath("/img/pay.webp") }
  ];

  useEffect(() => {
    const loadData = async () => {
      try {
        const data = await fetchWebControllerData();

        if (data.phonepeMode) {
          setPhonepeMode(data.phonepeMode);
        }

        // Load PayU config
        if (data.payu) {
          setPayuConfig(data.payu);
        }

        // Load Razorpay
        if (data.razorpay) {
          const fixedRazorpay = {
            ...data.razorpay,
            logo: resolvePath(data.razorpay.logo)
          };
          setRazorpayConfig(fixedRazorpay);
        }

        if (data.upiOptions) {
          const fixedUpiOptions = data.upiOptions.map(opt => ({
            ...opt,
            upiimg: resolvePath(opt.upiimg),
            paymentImages: opt.paymentImages ? opt.paymentImages.map(resolvePath) : undefined
          }));
          setUpiOptions(fixedUpiOptions);
        }

        // Priority-based default selection:
        // 1. PayU enabled -> select first PayU option (gpay)
        // 2. Razorpay enabled -> select Razorpay
        // 3. Neither -> select first UPI option
        if (data.payu && data.payu.enabled) {
          setSelectedOption("payu_gpay");
        } else if (data.razorpay && data.razorpay.enabled) {
          setSelectedOption("Razorpay");
        } else if (data.upiOptions && data.upiOptions.length > 0) {
          const defaultOpt = data.upiOptions.find(opt => opt.paymentName === "Google Pay") || data.upiOptions[0];
          if (defaultOpt) setSelectedOption(defaultOpt.paymentName);
        }

        if (data.facebookPixelId) {
          loadFacebookPixel(data.facebookPixelId);
        }
      } catch (err) {
        console.error("Error loading config:", err);
      }
    };
    loadData();
  }, []);

  useEffect(() => {
    if (timeLeft <= 0) return;
    const timer = setInterval(() => setTimeLeft((prev) => prev - 1), 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  const loadFacebookPixel = (pixelId) => {
    if (!window.fbq) {
      (function (f, b, e, v, n, t, s) {
        if (f.fbq) return;
        n = f.fbq = function () {
          n.callMethod ? n.callMethod(...arguments) : n.queue.push(arguments);
        };
        if (!f._fbq) f._fbq = n;
        n.push = n;
        n.loaded = true;
        n.version = "2.0";
        n.queue = [];
        t = b.createElement(e);
        t.async = true;
        t.src = "https://connect.facebook.net/en_US/fbevents.js";
        s = b.getElementsByTagName(e)[0];
        s.parentNode.insertBefore(t, s);
      })(window, document, "script");
    }
    window.fbq("init", pixelId);
    window.fbq("track", "PageView");
  };

  // ====== PayU Integration ======

  // Compose deep link from UPI string
  const composeAppLink = (app, sourceUpi) => {
    let upi = sourceUpi || "";
    try {
      upi = decodeURIComponent(String(upi));
    } catch { }

    if (!upi) return "";

    let query = "";
    if (upi.startsWith("upi://pay?")) {
      query = upi.substring(10);
    } else if (upi.includes("?")) {
      const qIndex = upi.indexOf("?");
      query = upi.substring(qIndex + 1);
    } else if (upi.includes("pa=")) {
      query = upi;
    } else if (upi.includes("@")) {
      query = `pa=${upi}`;
    } else {
      return "";
    }

    if (!query) return "";

    if (app === "gpay") return `tez://upi/pay?${query}`;
    if (app === "phonepe") return `phonepe://pay?${query}`;
    if (app === "paytm") return `paytmmp://pay?${query}`;

    return `upi://pay?${query}`;
  };

  // Create PayU payment request
  const createPayinRequest = async (payinData, upiAppName) => {
    if (!payuConfig || !payuConfig.backendUrl) {
      throw new Error("PayU backend not configured");
    }

    const payuData = {
      txnid: payinData.client_ref_id,
      amount: payinData.amount.toString(),
      productinfo: 'Order Payment',
      firstname: payinData.fname,
      lastname: payinData.lname || '',
      email: payinData.emailid || 'customer@example.com',
      phone: payinData.mobile_number || '9999999999',
      upiAppName: upiAppName,
      surl: `${payuConfig.backendUrl}/api/s2s-callback`,
      furl: `${payuConfig.backendUrl}/api/s2s-callback`
    };

    const response = await fetch(`${payuConfig.backendUrl}/api/initiate-payment`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(payuData),
    });

    const result = await response.json();

    if (result.success && result.data && result.data.result) {
      const intentURIData = result.data.result.intentURIData || '';
      let upiString = intentURIData;
      if (intentURIData && !intentURIData.startsWith('upi://')) {
        upiString = `upi://pay?${intentURIData}`;
      }

      return {
        status: 1,
        data: {
          qr_string: upiString,
          mihpayid: result.data.metaData?.referenceId || result.data.result.paymentId,
          referenceId: result.data.metaData?.referenceId,
          txnid: result.data.metaData?.txnId
        }
      };
    }

    return { error: result.error || "Payment initialization failed" };
  };

  // Handle PayU payment for specific app
  const handlePayUPayment = async (app) => {
    if (isProcessing) return;
    setIsProcessing(true);

    try {
      // Track Facebook pixel
      if (typeof window !== 'undefined' && window.fbq) {
        window.fbq('track', 'InitiateCheckout', {
          currency: 'INR',
          value: totalPrice,
        });
      }

      // Map app to PayU upiAppName
      const upiAppNameMap = {
        gpay: 'googlepay',
        phonepe: 'phonepe',
        paytm: 'paytm'
      };

      const payinData = {
        client_ref_id: `PAYIN${Date.now()}`,
        fname: "Customer",
        lname: "",
        emailid: "customer@example.com",
        mobile_number: "9999999999",
        amount: Number(totalPrice) || 0,
      };

      const res = await createPayinRequest(payinData, upiAppNameMap[app] || 'genericintent');

      if (!res) {
        alert("Payment initialization failed (no response).");
        setIsProcessing(false);
        return;
      }

      if (res?.status === 1 && res?.data?.qr_string) {
        const upiUrl = res.data.qr_string;
        setCurrentOrderId(payinData.client_ref_id);

        // Wait for state update
        await new Promise(resolve => setTimeout(resolve, 100));

        // Launch the app
        const link = composeAppLink(app, upiUrl);
        if (link) {
          window.location.href = link;
        } else {
          window.location.href = upiUrl;
        }

        // Show tracking popup after a short delay
        setIsProcessing(false);
        setTimeout(() => {
          setShowOrderTracking(true);
        }, 500);
      } else {
        console.error("PayU API Error:", res);
        alert(res.error || "Payment initialization failed. Please try again.");
        setIsProcessing(false);
      }
    } catch (error) {
      console.error("PayU Error:", error);
      alert("An error occurred. Please try again.");
      setIsProcessing(false);
    }
  };

  const handleRazorpayPayment = () => {
    if (!razorpayConfig || !razorpayConfig.enabled) {
      alert("Razorpay is not configured");
      return;
    }

    const options = {
      key: razorpayConfig.keyId,
      amount: Math.round(totalPrice * 100),
      currency: "INR",
      name: razorpayConfig.businessName || "Your Store",
      description: "Order Payment",
      image: razorpayConfig.logo || resolvePath("/img/100.webp"),
      handler: function (response) {
        navigate("/thank-you", {
          state: {
            amount: totalPrice,
            app: "Razorpay",
            paymentId: response.razorpay_payment_id
          }
        });
      },
      prefill: {
        name: razorpayConfig.prefill?.name || "",
        email: razorpayConfig.prefill?.email || "",
        contact: razorpayConfig.prefill?.contact || ""
      },
      notes: { cart_items: cart.length, total_amount: totalPrice },
      theme: { color: razorpayConfig.themeColor || "#2563eb" },
      modal: {
        ondismiss: function () { console.log("Payment cancelled by user"); }
      }
    };

    const razorpay = new window.Razorpay(options);
    razorpay.open();
    razorpay.on('payment.failed', function (response) {
      navigate("/payment-failed", {
        state: {
          error: response.error.description,
          cart: cart,
          totalPrice: totalPrice
        }
      });
    });
  };

  // Native UPI payment handler
  const handleNativeUpiPayment = () => {
    const selectedUpi = upiOptions.find(
      (option) => option.paymentName === selectedOption
    );

    if (!selectedUpi) {
      alert("Please select a valid payment option");
      return;
    }

    const amount = Number(totalPrice);
    const splitLink = selectedUpi.link.split('?');
    const urlParams = new URLSearchParams(splitLink.length > 1 ? splitLink[1] : "");
    const vpaFromJson = urlParams.get('pa');

    if (selectedOption === "PhonePe") {
      if (phonepeMode === 1) {
        const p2pData = {
          contact: { cbsName: "Merchant", nickName: "Store", vpa: vpaFromJson, type: "VPA" },
          p2pPaymentCheckoutParams: {
            note: "Order Payment", isByDefaultKnownContact: true, enableSpeechToText: false,
            allowAmountEdit: false, showQrCodeOption: false, disableViewHistory: true,
            shouldShowUnsavedContactBanner: false, isRecurring: false, checkoutType: "DEFAULT",
            transactionContext: "p2p", initialAmount: Math.round(amount * 100),
            disableNotesEdit: true, showKeyboard: true, currency: "INR", shouldShowMaskedNumber: true
          }
        };
        const base64Data = btoa(JSON.stringify(p2pData));
        window.location.href = `phonepe://native?data=${base64Data}&id=p2ppayment`;
      } else {
        const transactionRef = "RR" + Math.random().toString(36).slice(2, 10) + Date.now();
        const separator = selectedUpi.link.includes("?") ? "&" : "?";
        let link = selectedUpi.link;
        window.location.href = `${link}${separator}am=${amount}&tr=${transactionRef}&tn=OrderPayment`;
      }
    } else {
      const transactionRef = "RR" + Math.random().toString(36).slice(2, 10) + Date.now();
      const separator = selectedUpi.link.includes("?") ? "&" : "?";
      window.location.href = `${selectedUpi.link}${separator}am=${amount}&tr=${transactionRef}&tn=OrderPayment`;
    }

    setTimeout(() => {
      const confirmPay = window.confirm("Payment successful");
      if (confirmPay) {
        navigate("/thank-you", { state: { amount: amount, app: selectedOption } });
      }
    }, 5000);
  };

  // Unified Pay handler
  const handlePay = () => {
    if (!selectedOption) {
      alert("Please select a payment option");
      return;
    }

    // Check if PayU option is selected
    if (selectedOption.startsWith("payu_")) {
      const app = selectedOption.replace("payu_", "");
      handlePayUPayment(app);
      return;
    }

    // Razorpay
    if (selectedOption === "Razorpay") {
      handleRazorpayPayment();
      return;
    }

    // Native UPI
    handleNativeUpiPayment();
  };

  if (!cart.length) {
    return (
      <div style={{ textAlign: "center", padding: "50px" }}>
        <h2>No payment data found!</h2>
        <button onClick={() => navigate("/")} style={{ padding: "10px 20px", background: "#2563eb", color: "#fff", border: "none", marginTop: "20px" }}>Go Back</button>
      </div>
    );
  }

  const isRazorpayEnabled = razorpayConfig && razorpayConfig.enabled;
  const isPayuEnabled = payuConfig && payuConfig.enabled;

  // Determine which mode to show based on priority
  // Priority: PayU > Razorpay > Native UPI
  const showPayuOptions = isPayuEnabled;
  const showRazorpay = !isPayuEnabled && isRazorpayEnabled;
  const showNativeUpi = !isPayuEnabled && !isRazorpayEnabled;

  return (
    <div className="payment-container-new">
      {/* Header */}
      <div className="payment-header-new">
        <div className="header-left">
          <button onClick={() => navigate(-1)} className="back-btn-new">
            <i className="fa-solid fa-arrow-left"></i>
          </button>
          <div className="header-titles">
            <span className="step-count">Step 3 of 3</span>
            <h2 className="page-title">Payments</h2>
          </div>
        </div>
        <div className="secure-badge">
          <i className="fa-solid fa-shield-halved"></i> 100% Secure
        </div>
      </div>

      {/* Order Summary */}
      <div className="summary-card">
        <div className="summary-row">
          <span>Price ({cart.length} items)</span>
          <span>₹{cart.reduce((sum, item) => sum + Number(String(item.disprice).replace(/\D/g, "")) * item.quantity, 0).toLocaleString()}</span>
        </div>
        <div className="summary-row">
          <span>Protect Promise Fee</span>
          <span>₹{protectPromiseFee}</span>
        </div>
        <div className="summary-row total-row-new">
          <span className="total-label-new">Total Amount <i className="fa-solid fa-chevron-up" style={{ fontSize: '12px', marginLeft: '5px' }}></i></span>
          <span className="total-value-new">₹{totalPrice.toLocaleString()}</span>
        </div>
      </div>

      {/* Cashback Banner */}
      <div className="cashback-banner">
        <div className="cashback-content">
          <strong className="cashback-title">5% Cashback</strong>
          <span className="cashback-sub">Claim now with payment offers</span>
        </div>
        <div className="cashback-icons">
          <img src={resolvePath("/img/axis.png")} alt="Axis Bank" style={{ height: '24px', objectFit: 'contain' }} />
          <img src={resolvePath("/img/sbi.png")} alt="SBI" style={{ height: '24px', objectFit: 'contain' }} />
        </div>
      </div>

      {/* UPI Section */}
      <div className="payment-section-card expanded">
        <div className="payment-section-header">
          <div className="section-header-left">
            <div className="section-icon-box">
              <span style={{ fontWeight: 'bold', fontSize: '12px' }}>UPI</span>
            </div>
            <div className="section-text">
              <span className="section-title">UPI</span>
              <span className="section-subtitle">Pay by any UPI app</span>
            </div>
          </div>
          <i className="fa-solid fa-chevron-down decoration-icon"></i>
        </div>

        <div className="payment-section-body">
          <div className="upi-app-list">

            {/* PayU Options (radio button style like native UPI) */}
            {showPayuOptions && payuUpiOptions.map((option) => (
              <label key={option.id} className="upi-option-row">
                <div className="upi-option-left">
                  <img
                    src={option.icon}
                    alt={option.name}
                    className="app-icon"
                  />
                  <span className="upi-label">{option.name}</span>
                </div>
                <input
                  type="radio"
                  name="paymentMethod"
                  value={`payu_${option.id}`}
                  checked={selectedOption === `payu_${option.id}`}
                  onChange={() => setSelectedOption(`payu_${option.id}`)}
                  className="radio-new"
                />
              </label>
            ))}

            {/* Razorpay Option */}
            {showRazorpay && (
              <label className="upi-option-row">
                <div className="upi-option-left">
                  <img src="https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/UPI-Logo-vector.svg/320px-UPI-Logo-vector.svg.png" alt="UPI" className="app-icon" style={{ width: '40px' }} />
                  <span className="upi-label" style={{ fontWeight: 'bold' }}>Cards, UPI, NetBanking</span>
                </div>
                <input
                  type="radio"
                  name="paymentMethod"
                  value="Razorpay"
                  checked={selectedOption === "Razorpay"}
                  onChange={() => setSelectedOption("Razorpay")}
                  className="radio-new"
                />
              </label>
            )}

            {/* Native UPI Options */}
            {showNativeUpi && upiOptions.map((option) => (
              <label key={option.paymentName} className="upi-option-row">
                <div className="upi-option-left">
                  <img src={option.upiimg} alt={option.paymentName} className="app-icon" />
                  <span className="upi-label">{option.paymentName}</span>
                </div>
                <input
                  type="radio"
                  name="paymentMethod"
                  value={option.paymentName}
                  checked={selectedOption === option.paymentName}
                  onChange={() => setSelectedOption(option.paymentName)}
                  className="radio-new"
                />
              </label>
            ))}
          </div>

          {/* Processing indicator */}
          {isProcessing && (
            <div style={{
              marginTop: '16px',
              padding: '12px',
              backgroundColor: '#eff6ff',
              borderRadius: '8px',
              textAlign: 'center'
            }}>
              <div style={{
                display: 'inline-block',
                width: '20px',
                height: '20px',
                border: '2px solid #e5e7eb',
                borderTop: '2px solid #2563eb',
                borderRadius: '50%',
                animation: 'spin 1s linear infinite',
                marginRight: '10px',
                verticalAlign: 'middle'
              }}></div>
              <span style={{ color: '#1e40af', fontWeight: '500' }}>Initiating payment...</span>
            </div>
          )}

          <button
            className="pay-btn-yellow"
            onClick={handlePay}
            disabled={!selectedOption || isProcessing}
          >
            PAY ₹{totalPrice.toLocaleString()}
          </button>
        </div>
      </div>

      {/* Other (Unavailable) Sections */}
      <div className="payment-section-card collapsed">
        <div className="payment-section-header">
          <div className="section-header-left">
            <i className="fa-regular fa-credit-card section-icon-simple"></i>
            <div className="section-text">
              <span className="section-title">Credit/Debit/ATM Card</span>
              <span className="section-subtitle">Add and secure cards as per RBI guidelines</span>
              <span className="offer-text-green">Get upto 5% cashback* • 2 offers available</span>
            </div>
          </div>
          <span className="unavailable-text">Unavailable <i className="fa-regular fa-circle-question"></i></span>
        </div>
      </div>

      <div className="payment-section-card collapsed">
        <div className="payment-section-header">
          <div className="section-header-left">
            <i className="fa-solid fa-building-columns section-icon-simple"></i>
            <span className="section-title">Net Banking</span>
          </div>
          <span className="unavailable-text">Unavailable <i className="fa-regular fa-circle-question"></i></span>
        </div>
      </div>

      <div className="payment-section-card collapsed">
        <div className="payment-section-header">
          <div className="section-header-left">
            <i className="fa-solid fa-money-bill section-icon-simple"></i>
            <span className="section-title">Cash on Delivery</span>
          </div>
          <span className="unavailable-text">Unavailable <i className="fa-regular fa-circle-question"></i></span>
        </div>
      </div>

      {/* Trust Footer */}
      <div className="trust-footer">
        <p>35 Crore happy customers and counting!</p>
        <div className="smile-icon">
          <i className="fa-regular fa-face-smile"></i>
        </div>
      </div>

      {/* OrderTrackingPopup for PayU */}
      <OrderTrackingPopup
        isOpen={showOrderTracking}
        onClose={() => setShowOrderTracking(false)}
        orderId={currentOrderId}
        backendUrl={payuConfig?.backendUrl || ''}
        cart={cart}
        totalPrice={totalPrice}
      />

      <style>{`
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default Payment;
