import React from "react";
import { Route, Routes, Navigate, useLocation } from "react-router-dom";

import Home from "./components/pages/Home";
import ProductDetail from "./components/pages/ProductDetail";
import CartPage from "./components/pages/CartPage";
import Address from "./components/pages/Address";
import Summary from "./components/pages/Summary";
import Payment from "./components/pages/Payment";
import Thankyou from "./components/pages/Thankyou";
import ContinuePage from "./components/pages/ContinuePage";
import NotFound from "./components/pages/NotFound";
import PaymentFailed from "./components/pages/PaymentFailed";
import ProtectedRoute from "./components/ProtectedRoute";

const isMetaBrowser = () => {
  const ua = navigator.userAgent || navigator.vendor || window.opera;
  return ua.includes("FBAN") || ua.includes("FBAV") || ua.includes("Instagram");
};

function AppRoute() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);
  const hasSecretKey = queryParams.get("access") === "granted";


  // remove true to allow redirects
  if (true || hasSecretKey) {
    sessionStorage.setItem("allowSite", "true");
    // return <Navigate to="/home" replace />;
  }
  const hasAccess = sessionStorage.getItem("allowSite") === "true";

  return (
    <Routes>
      <Route
        path="/"
        element={
          isMetaBrowser() ? (
            hasAccess ? <Navigate to="/home" replace /> : <ContinuePage />
          ) : (
            hasAccess ? <Navigate to="/home" replace /> : <Navigate to="/404" replace />
          )
        }
      />

      <Route element={<ProtectedRoute />}>
        <Route path="/home" element={<Home />} />
        <Route path="/ProductDetail/:id" element={<ProductDetail />} />
        <Route path="/cart" element={<CartPage />} />
        <Route path="/address" element={<Address />} />
        <Route path="/order-summary" element={<Summary />} />
        <Route path="/payment" element={<Payment />} />
        <Route path="/thank-you" element={<Thankyou />} />
        <Route path="/payment-failed" element={<PaymentFailed />} />
      </Route>

      <Route path="/404" element={<NotFound />} />
      <Route path="*" element={<Navigate to="/404" replace />} />
    </Routes>
  );
}

export default AppRoute;




