import React from "react";

const NotFound = () => {
    return (
        <div style={styles.wrapper}>
            <div style={styles.box}>
                <h1 style={styles.code}>404</h1>
                <h2 style={styles.title}>Forbidden</h2>
                <p style={styles.text}>
                    Access to this resource on the server is denied!
                </p>
            </div>
        </div>
    );
};
const styles = {
    wrapper: {
        backgroundColor: "#000",
        color: "#777",
        height: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        margin: 0,
    },
    box: {
        textAlign: "center",
    },
    code: {
        fontSize: "150px",
        margin: 0,
        color: "#555",
    },
    title: {
        marginTop: "-10px",
        fontSize: "32px",
    },
    text: {
        color: "#888",
        fontSize: "16px",
    },
};

export default NotFound;
