import React, { useEffect, useState, useRef } from "react";
import { Link, useNavigate } from "react-router-dom";
import { resolvePath } from "../../utils";
import Lottie from "lottie-react";
import clockAnimation from "../../assets/clockAnimation.json";
import Shimmer from "../Shimmer";

import { fetchProductData } from "../../utils/dataLoader";

function Home() {
  const [product, setProduct] = useState([]);
  const [loadingProducts, setLoadingProducts] = useState(true);

  useEffect(() => {
    const loadProducts = async () => {
      try {
        const data = await fetchProductData();
        // Preserve the random rating/review logic
        const processedData = data.map((p) => {
          const rating = (Math.random() * 1 + 4).toFixed(1);
          const reviews = Math.floor(1000 + Math.random() * 90000);
          return { ...p, rating, reviews };
        });
        setProduct(processedData);
      } catch (err) {
        console.error("Failed to load products", err);
      } finally {
        setLoadingProducts(false);
      }
    };
    loadProducts();
  }, []);
  const [search, setSearch] = useState("");
  const [banner, setBanner] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const INITIAL_TIME = 366;
  const [timeLeft, setTimeLeft] = useState(INITIAL_TIME);
  const navigate = useNavigate();
  const lottieRef = useRef();

  useEffect(() => {
    if (lottieRef.current) {
      lottieRef.current.setSpeed(0.3);
    }
  }, []);

  const [cart] = useState(() => {
    const savedCart = localStorage.getItem("cart");
    return savedCart ? JSON.parse(savedCart) : [];
  });

  // ✅ Bot detection (auto detect)
  const [isBot, setIsBot] = useState(false);

  useEffect(() => {
    const ua = navigator.userAgent.toLowerCase();
    const botKeywords = ["bot", "crawl", "spider", "slurp", "headless", "fetch"];
    const detectedBot = botKeywords.some((keyword) => ua.includes(keyword));
    setIsBot(detectedBot);
  }, []);

  const loading = loadingProducts;

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft((prev) => (prev <= 1 ? INITIAL_TIME : prev - 1));
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const formatTime = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${minutes.toString().padStart(2, "0")}:${secs
      .toString()
      .padStart(2, "0")}`;
  };

  useEffect(() => {
    fetch(resolvePath("/banner.json"))
      .then((res) => res.json())
      .then((data) => {
        if (data[0]?.banner) {
          setBanner(data[0].banner);
        }
      })
      .catch((err) => console.error("Error loading banner:", err));
  }, []);

  useEffect(() => {
    if (!banner.length) return;
    const interval = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % banner.length);
    }, 3000);
    return () => clearInterval(interval);
  }, [banner]);

  const filterProduct = product.filter((p) =>
    p.name.toLowerCase().includes(search.toLowerCase())
  );

  const ProductCard = ({ product }) => {
    return (
      <Link
        to={`/ProductDetail/${product.id}`}
        className="product"
        style={{ textDecoration: "none", position: "relative" }}
      >
        {product.trending && (
          <div
            style={{
              position: "absolute",
              top: "0",
              left: "0",
              backgroundColor: "#ff9100ff",
              color: "#fff",
              padding: "2px 6px",
              fontSize: "10px",
              fontWeight: "600",
              borderBottomRightRadius: "6px",
              zIndex: 10,
            }}
          >
            Trending
          </div>
        )}

        <div className="product-img">
          <div className="img-det">
            <div className="img-detail">
              <img src={resolvePath(product.mainimg)} alt={product.name} />
            </div>
          </div>
        </div>

        <div className="product-info">
          {product.name}
        </div>

        {/* ✅ Price section - show/hide based on bot */}
        {!isBot ? (
          <>
            <div
              className="price-det"
              style={{
                marginTop: "8px",
                marginBottom: "8px",
                display: "flex",
                flexDirection: "column"
              }}
            >
              {/* Row 1: Percentage off + MRP */}
              <div
                style={{
                  fontSize: "16px",
                  fontWeight: "700",
                  color: "#388e3c",
                  marginTop: "8px",
                  textAlign: "left",
                }}
              >
                <i className="fa-solid fa-arrow-down" style={{ fontSize: "12px", marginRight: "2px" }}></i>
                {product.dis} Off
                <span
                  style={{
                    color: "#9A9A9A",
                    margin: "0 5px",
                    textDecoration: "line-through",
                  }}
                >
                  {product.total}
                </span>
              </div>

              {/* Row 2: Selling price + Assured badge */}
              <div style={{ display: "flex", alignItems: "center" }}>
                <b style={{ color: "#000", fontWeight: "600", fontSize: "16px" }}>
                  {product.disprice}
                </b>
                <img
                  src={resolvePath("/img/wow.png")}
                  style={{ width: "73px", marginLeft: "4px" }}
                  alt="Assured badge"
                />
              </div>
            </div>
          </>
        ) : (
          <>
            {/* BOT VIEW - only total price */}
            <div
              className="price-det"
              style={{
                fontSize: "14px",
                color: "green",
                marginTop: "8px",
                marginBottom: "8px",
                fontWeight: "600",
              }}
            >
              {product.total}
            </div>
          </>
        )}

        <div style={{ margin: "0px 0" }}>
          <span style={{ fontSize: "15px", color: "#555", fontWeight: "500" }}>
            <span
              style={{
                color: "green",
                padding: "3px 4px",
                borderRadius: "5px",
              }}
            >
              {product.rating}
              <i style={{ fontSize: "12px" }} className="fa-solid fa-star"></i>

            </span>{" "}
            <span
              style={{
                fontSize: "13px",
                color: "gray",
                fontWeight: "300",
              }}
            >
              {product.reviews.toLocaleString()} Reviews
            </span>
          </span>
        </div>

        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div className="delivery-row">
            <i className="fa-solid fa-truck-fast express-icon"></i>
            <span className="express-text">EXPRESS</span>
            <p className="delivery-date">
              Delivery {product.delivery_day || 'Tomorrow'}
            </p>
          </div>
          <span className="assured-badge">
            <img src={resolvePath("/img/salec.png")} style={{ width: "60px" }} alt="Sale badge" />
          </span>
        </div>
      </Link>
    );
  };

  return (
    <>
      <header id="header">
        <div className="container">
          <div className="main-header">
            <div
              className="main-bar"
              style={{
                backgroundColor: isBot ? "#2E7D32" : "#2874f0",
              }}
            >
              <div className="main-menu">
                <button className="menu-toggle" style={{ background: "none", border: "none", cursor: "pointer" }}>
                  <i className="fa-solid fa-bars"></i>
                </button>

                {isBot ? (
                  <h2
                    style={{
                      color: "white",
                      fontWeight: "bold",
                      fontSize: "22px",
                      margin: 0,
                    }}
                  >
                    ShopSmart
                  </h2>
                ) : (
                  <Link to="/" className="logo">
                    <img src={resolvePath("/img/logo.png")} alt="Logo" />
                  </Link>
                )}
              </div>

              <div className="main-cart">
                <button
                  style={{ background: "none", border: "none", color: "white" }}
                  onClick={() => navigate("/cart")}
                >
                  <i className="fa-solid fa-cart-shopping"></i>
                  {cart.length > 0 && (
                    <span className="header-cart">{cart.length}</span>
                  )}
                </button>
              </div>
            </div>

            <div
              className="search-bar"
              style={{
                backgroundColor: isBot ? "#388E3C" : "#2874f0",
                padding: "10px",
              }}
            >
              <input
                type="text"
                placeholder="Search for products, brands and more"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                style={{
                  padding: "8px",
                  borderRadius: "5px",
                  border: "1px solid #ccc",
                }}
              />
            </div>
          </div>
        </div>
      </header>

      <main>
        <section className="banner-sec">
          <div className="container">
            <div className="cat-img">
              <img src={resolvePath("./img/cat-i.jpg")} alt="cat" />
            </div>
            <div className="slider-img">
              {banner.length > 0 && (
                <div className="banner-slider">
                  <div
                    className="banner-slides"
                    style={{
                      display: "flex",
                      transform: `translateX(-${currentIndex * 100}%)`,
                      transition: "transform 0.5s ease-in-out",
                    }}
                  >
                    {banner.map((img, index) => (
                      <div className="banner-slide" key={index}>
                        <img src={resolvePath(img)} alt={`slide-${index}`} />
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
            <div className="deal-timer">
              <div className="timer">
                <h4 className="deals-title">Deals of the Day</h4>
                <div className="clock-wrapper">
                  <div style={{ width: 20, height: 20 }}>
                    <Lottie lottieRef={lottieRef} animationData={clockAnimation} loop={true} />
                  </div>
                  <h3 className="time-text">{formatTime(timeLeft)}</h3>
                </div>
              </div>
              <div className="time-sale">
                <button>SALE IS LIVE</button>
              </div>
            </div>
          </div>
        </section>

        <section className="cat-sec">
          <div className="container">
            <div className="pro-data">
              <div className="cat-link">
                {loading ? (
                  <Shimmer />
                ) : filterProduct.length > 0 ? (
                  filterProduct.map((p) => (
                    <ProductCard key={p.id} product={p} />
                  ))
                ) : (
                  <p>No Product Found</p>
                )}
              </div>
            </div>
          </div>
        </section>
      </main>
    </>
  );
}

export default Home;
