import React, { useEffect, useState } from "react";
import { fetchWebControllerData } from "../../utils/dataLoader";
import { resolvePath } from "../../utils";

const Loader = () => {
  const [logo, setLogo] = useState(resolvePath("/img/flipkart-logo.webp"));
  const [enabled, setEnabled] = useState(true);

  useEffect(() => {
    const fetchConfig = async () => {
      try {
        const data = await fetchWebControllerData();

        if (data.loaderEnabled !== undefined) setEnabled(data.loaderEnabled);
        if (data.loaderLogo) setLogo(resolvePath(data.loaderLogo));
      } catch (err) {
        console.error("Error loading JSON config:", err);
      }
    };
    fetchConfig();
  }, []);

  if (!enabled) return null;

  return (
    <div className="page-loader">
      <div className="loader-content">
        <img src={logo} alt="Logo" className="loader-logo" />
      </div>
    </div>
  );
};

export default Loader;
