import React, { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import {
  Box,
  Step,
  StepLabel,
  Stepper,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from "@mui/material";

const steps = ["Address", "Order Summary", "Payment"];

const states = [
  "Andhra Pradesh", "Arunachal Pradesh", "Assam", "Bihar", "Chhattisgarh",
  "Goa", "Gujarat", "Haryana", "Himachal Pradesh", "Jammu & Kashmir",
  "Jharkhand", "Karnataka", "Kerala", "Madhya Pradesh", "Maharashtra",
  "Manipur", "Meghalaya", "Mizoram", "Nagaland", "Odisha",
  "Punjab", "Rajasthan", "Sikkim", "Tamil Nadu", "Telangana",
  "Tripura", "Uttarakhand", "Uttar Pradesh", "West Bengal",
  "Andaman & Nicobar", "Chandigarh", "Dadra and Nagar Haveli",
  "Daman & Diu", "Delhi", "Lakshadweep", "Puducherry",
];

function Address() {
  const navigate = useNavigate();
  const location = useLocation();

  const [formData, setFormData] = useState({
    fullName: "",
    mobile: "",
    pincode: "",
    city: "",
    state: "",
    house: "",
    road: "",
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const requiredFields = ["fullName", "mobile", "pincode", "city", "state", "house", "road"];
    const emptyFields = requiredFields.filter((field) => !formData[field]);
    if (emptyFields.length > 0) {
      alert("Please fill all required fields before proceeding.");
      return;
    }

    localStorage.setItem(
      "user",
      JSON.stringify({
        address: formData.house,
        name: formData.fullName,
        phone: Number(formData.mobile),
      })
    );

    const cart = location.state?.cart || [];
    const product = location.state?.product;

    navigate("/order-summary", {
      state: {
        address: formData,
        cart: cart.length > 0 ? cart : product ? [product] : [],
      },
    });
  };

  return (
    <div className="container">

      <div style={{ background: "#fff", padding: "16px" }}>
        <div style={{ maxWidth: "400px", margin: "0 auto", display: "flex", alignItems: "center", marginBottom: "20px" }}>
          <button
            onClick={() => navigate(-1)}
            style={{ fontSize: "18px", marginRight: "10px", background: "none", border: "none", cursor: "pointer" }}
          >
            <i className="fa-solid fa-arrow-left"></i>
          </button>
          <h2 style={{ fontSize: "16px", fontWeight: "600" }}>Add delivery address</h2>
        </div>

        <Box sx={{ width: "100%", maxWidth: "400px", margin: "0 auto" }}>
          <Stepper activeStep={0} alternativeLabel>
            {steps.map((label) => (
              <Step key={label}>
                <StepLabel>{label}</StepLabel>
              </Step>
            ))}
          </Stepper>
        </Box>

        <form
          onSubmit={handleSubmit}
          style={{ maxWidth: "400px", margin: "20px auto 0", paddingBottom: "80px", display: "flex", flexDirection: "column", gap: "16px" }}
        >
          <TextField
            label="Full Name (Required)*"
            variant="outlined"
            name="fullName"
            value={formData.fullName}
            onChange={handleChange}
            required
            fullWidth
            size="medium"
          />

          <TextField
            label="Mobile Number (Required)*"
            variant="outlined"
            name="mobile"
            value={formData.mobile}
            onChange={handleChange}
            required
            fullWidth
            size="medium"
          />

          <TextField
            label="Pincode (Required)*"
            variant="outlined"
            name="pincode"
            value={formData.pincode}
            onChange={handleChange}
            required
            fullWidth
            type="number"
            size="medium"
          />

          <div style={{ display: "flex", gap: "10px", width: "100%" }}>
            <div style={{ flex: 1 }}>
              <TextField
                label="City (Required)*"
                variant="outlined"
                name="city"
                value={formData.city}
                onChange={handleChange}
                required
                fullWidth
                size="medium"
              />
            </div>

            <div style={{ flex: 1 }}>
              <FormControl fullWidth required>
                <InputLabel id="state-select-label">State (Required)*</InputLabel>
                <Select
                  labelId="state-select-label"
                  id="state-select"
                  name="state"
                  value={formData.state}
                  label="State (Required)*"
                  onChange={handleChange}
                  MenuProps={{ PaperProps: { sx: { bgcolor: "#fff" } } }}
                >
                  {states.map((s) => (
                    <MenuItem key={s} value={s}>{s}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </div>
          </div>

          <TextField
            label="House No., Building Name (Required)*"
            variant="outlined"
            name="house"
            value={formData.house}
            onChange={handleChange}
            required
            fullWidth
            size="medium"
          />

          <TextField
            label="Road name, Area, Colony (Required)*"
            variant="outlined"
            name="road"
            value={formData.road}
            onChange={handleChange}
            required
            fullWidth
            size="medium"
          />

          <button
            type="submit"
            style={{
              background: "#ffc107",
              color: "#000",
              position: "fixed",
              bottom: "7px",
              left: "0px",
              right: "0px",
              padding: "13px",
              border: "none",
              borderRadius: "3px",
              fontWeight: "600",
              fontSize: "16px",
              cursor: "pointer",
              width: "318px",
              margin: "0 auto",
              zIndex: 1000,
            }}
          >
            Save Address
          </button>
        </form>
      </div>
    </div>
  );
}

export default Address;
