import React, { useState, useEffect, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { resolvePath } from "../../utils";
import Rating from "@mui/material/Rating";
import Box from "@mui/material/Box";

function CartPage() {
  const navigate = useNavigate();
  const [isBot, setIsBot] = useState(false);

  const [cart, setCart] = useState(() => {
    const savedCart = localStorage.getItem("cart");
    return savedCart ? JSON.parse(savedCart) : [];
  });

  const [savedForLater, setSavedForLater] = useState(() => {
    const saved = localStorage.getItem("savedForLater");
    return saved ? JSON.parse(saved) : [];
  });

  // Generate stable random ratings per item (won't re-randomize on re-render)
  const itemRatings = useMemo(() => {
    const map = {};
    cart.forEach((item) => {
      map[item.id] = {
        rating: (Math.random() * 0.9 + 4.0).toFixed(1),
        count: Math.floor(20000 + Math.random() * 80000),
      };
    });
    return map;
    // eslint-disable-next-line
  }, [cart.length]);

  useEffect(() => {
    const ua = navigator.userAgent.toLowerCase();
    const botPatterns = [
      "bot", "crawler", "spider", "headless", "slurp",
      "curl", "wget", "python-requests", "axios", "node"
    ];
    const isBotDetected =
      botPatterns.some((pattern) => ua.includes(pattern)) ||
      navigator.webdriver ||
      window._phantom ||
      window.callPhantom ||
      window.__nightmare;
    setIsBot(isBotDetected);
  }, []);

  const updateQty = (id, qty) => {
    const newCart = cart.map((item) => (item.id === id ? { ...item, quantity: qty } : item));
    setCart(newCart);
    localStorage.setItem("cart", JSON.stringify(newCart));
  };

  const removeItem = (id) => {
    const newCart = cart.filter((item) => item.id !== id);
    setCart(newCart);
    localStorage.setItem("cart", JSON.stringify(newCart));
  };

  const saveForLater = (id) => {
    const isAlreadySaved = savedForLater.some((item) => item.id === id);

    if (isAlreadySaved) {
      // If already saved, remove it (toggle off)
      const newSaved = savedForLater.filter((item) => item.id !== id);
      setSavedForLater(newSaved);
      localStorage.setItem("savedForLater", JSON.stringify(newSaved));
    } else {
      // If not saved, add it (toggle on)
      const itemToSave = cart.find((item) => item.id === id);
      if (itemToSave) {
        const newSaved = [...savedForLater, itemToSave];
        setSavedForLater(newSaved);
        localStorage.setItem("savedForLater", JSON.stringify(newSaved));
      }
    }
    // Do NOT remove from cart
  };

  const moveToCart = (id) => {
    const itemToMove = savedForLater.find((item) => item.id === id);
    if (itemToMove) {
      const isAlreadyInCart = cart.some((item) => item.id === id);

      if (!isAlreadyInCart) {
        const newCart = [...cart, itemToMove];
        setCart(newCart);
        localStorage.setItem("cart", JSON.stringify(newCart));
      }

      // Always remove from saved list when moving "back" to cart (or if it was already there)
      const newSaved = savedForLater.filter((item) => item.id !== id);
      setSavedForLater(newSaved);
      localStorage.setItem("savedForLater", JSON.stringify(newSaved));
    }
  };

  const removeSavedItem = (id) => {
    const newSaved = savedForLater.filter((item) => item.id !== id);
    setSavedForLater(newSaved);
    localStorage.setItem("savedForLater", JSON.stringify(newSaved));
  };

  const totalMRP = cart.reduce(
    (sum, item) => sum + Number(String(item.total).replace(/[₹,]/g, "")) * item.quantity, 0
  );

  const totalPrice = cart.reduce(
    (sum, item) => sum + Number(String(item.disprice).replace(/[₹,]/g, "")) * item.quantity, 0
  );

  const totalDiscount = totalMRP - totalPrice;

  const handleCheckout = () => navigate("/address", { state: { cart } });

  if (cart.length === 0) {
    return (
      <div className="container">
        <div style={{ display: "flex", alignItems: "center", padding: "12px 16px" }}>
          <button onClick={() => navigate(-1)} style={{ fontSize: "16px", marginRight: "10px", cursor: "pointer", border: "none", background: "none" }}>
            <i className="fa-solid fa-arrow-left"></i>
          </button>
          <h2 style={{ fontSize: "16px", fontWeight: "500", margin: 0 }}>My Cart</h2>
        </div>
        <div style={{ textAlign: "center", padding: "83px" }}>
          <h2 style={{ fontWeight: "400" }}>Cart Is Empty</h2>
          <button onClick={() => navigate("/")} className="ship-btn">Continue Shopping</button>
        </div>
      </div>
    );
  }

  return (
    <div className="container" style={{ background: "#f1f3f6", minHeight: "100vh" }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", padding: "12px 16px", background: "#fff", borderBottom: "1px solid #e0e0e0" }}>
        <button onClick={() => navigate(-1)} style={{ fontSize: "16px", cursor: "pointer", border: "none", background: "none", padding: 0, marginRight: "16px" }}>
          <i className="fa-solid fa-arrow-left"></i>
        </button>
        <h2 style={{ fontSize: "16px", fontWeight: "500", margin: 0 }}>My Cart</h2>
      </div>

      {/* Product Cards */}
      <div style={{ paddingBottom: "80px" }}>
        {cart.map((item) => {
          const r = itemRatings[item.id] || { rating: "4.2", count: 50000 };
          return (
            <div key={item.id} style={{ background: "#fff", marginBottom: "8px", padding: "16px" }}>
              {/* Product row */}
              <div style={{ display: "flex", gap: "14px" }}>
                {/* Left: image + qty */}
                <div style={{ display: "flex", flexDirection: "column", alignItems: "center", minWidth: "75px" }}>
                  <img
                    src={resolvePath(item.mainimg)}
                    alt={item.name}
                    style={{ width: "75px", height: "75px", objectFit: "contain" }}
                  />
                  <select
                    value={item.quantity}
                    onChange={(e) => updateQty(item.id, Number(e.target.value))}
                    style={{
                      marginTop: "8px",
                      padding: "3px 6px",
                      border: "1px solid #c2c2c2",
                      borderRadius: "3px",
                      fontSize: "12px",
                      color: "#212121",
                      background: "#fff",
                    }}
                  >
                    {[...Array(10).keys()].map((n) => (
                      <option key={n + 1} value={n + 1}>Qty: {n + 1}</option>
                    ))}
                  </select>
                </div>

                {/* Right: details */}
                <div style={{ flex: 1 }}>
                  {/* Product name */}
                  <p style={{ margin: 0, fontSize: "15px", fontWeight: "500", color: "#212121", lineHeight: 1.4 }}>
                    {item.name}
                  </p>

                  {/* Rating row */}
                  <Box sx={{ display: "flex", alignItems: "center", mt: 0.5, fontSize: 12 }}>
                    <Rating
                      value={parseFloat(r.rating)}
                      precision={0.1}
                      readOnly
                      size="small"
                      sx={{
                        "& .MuiRating-iconFilled": { color: "#008c00" },
                        "& .MuiRating-iconEmpty": { color: "#bdbdbd" },
                      }}
                    />
                    <span style={{ marginLeft: 4, color: "#878787", fontSize: "12px" }}>
                      {r.rating} ({r.count.toLocaleString()})
                    </span>
                    <img
                      src={resolvePath("/img/wow.png")}
                      alt="Assured"
                      style={{ height: "16px", marginLeft: "6px" }}
                    />
                  </Box>

                  {/* Price row */}
                  <div style={{ display: "flex", alignItems: "baseline", gap: "8px", marginTop: "6px" }}>
                    {isBot ? (
                      <span style={{ fontWeight: "600", fontSize: "16px" }}>{item.total}</span>
                    ) : (
                      <>
                        <span style={{ color: "#388e3c", fontWeight: "700", fontSize: "16px" }}>
                          <i className="fa-solid fa-arrow-down" style={{ fontSize: "12px", marginRight: "2px" }}></i>{item.dis} Off
                        </span>
                        <span style={{ textDecoration: "line-through", color: "#878787", fontSize: "14px" }}>
                          {item.total}
                        </span>
                        <span style={{ fontWeight: "700", fontSize: "18px", color: "#212121" }}>
                          ₹{String(item.disprice).replace(/[₹]/g, "")}
                        </span>
                      </>
                    )}
                  </div>

                  {/* WOW offer row */}
                  {!isBot && (
                    <div style={{ display: "flex", alignItems: "center", marginTop: "4px", gap: "4px" }}>
                      <img src={resolvePath("/img/wow.png")} alt="WOW" style={{ height: "18px" }} />
                      <span style={{ fontSize: "13px", color: "#212121" }}>Buy at <span style={{ fontWeight: "500" }}>₹{Math.max(Number(String(item.disprice).replace(/[₹,]/g, "")) - 50, 99).toLocaleString("en-IN")}</span></span>
                    </div>
                  )}
                </div>
              </div>

              {/* Delivery row */}
              <div style={{ display: "flex", alignItems: "center", marginTop: "14px", gap: "6px" }}>
                <i className="fa-solid fa-truck-fast" style={{ fontSize: "14px", color: "#2874f0" }}></i>
                <span style={{ fontSize: "12px", letterSpacing: "0.5px" }}>EXPRESS</span>
                <span style={{ fontSize: "13px", color: "#212121" }}>Delivery by tomorrow, 11 PM</span>
              </div>

              {/* Action buttons row */}
              <div style={{ display: "flex", borderTop: "1px solid #f0f0f0", marginTop: "14px", paddingTop: "10px" }}>
                <button onClick={() => removeItem(item.id)} style={{ flex: 1, background: "none", border: "none", borderRight: "1px solid #f0f0f0", cursor: "pointer", fontSize: "13px", color: "#212121", padding: "4px 0", display: "flex", alignItems: "center", justifyContent: "center", gap: "5px" }}>
                  <i className="fa-regular fa-trash-can" style={{ fontSize: "13px" }}></i> Remove
                </button>
                <button onClick={() => saveForLater(item.id)} style={{ flex: 1, background: "none", border: "none", borderRight: "1px solid #f0f0f0", cursor: "pointer", fontSize: "13px", color: "#212121", padding: "4px 0", display: "flex", alignItems: "center", justifyContent: "center", gap: "5px" }}>
                  <i className={`fa-${savedForLater.some(saved => saved.id === item.id) ? "solid" : "regular"} fa-bookmark`} style={{ fontSize: "13px" }}></i>
                  {savedForLater.some(saved => saved.id === item.id) ? "Saved" : "Save for later"}
                </button>
                <button onClick={() => navigate(`/ProductDetail/${item.id}`)} style={{ flex: 1, background: "none", border: "none", cursor: "pointer", fontSize: "13px", color: "#212121", padding: "4px 0", display: "flex", alignItems: "center", justifyContent: "center", gap: "5px" }}>
                  <i className="fa-solid fa-bolt" style={{ fontSize: "13px" }}></i> Buy this now
                </button>
              </div>
            </div>
          );
        })}

        {/* Saved For Later Section */}
        {savedForLater.length > 0 && (
          <div style={{ marginTop: "16px", background: "#fff", padding: "16px" }}>
            <h3 style={{ fontSize: "16px", fontWeight: "600", margin: "0 0 14px 0", paddingBottom: "12px", borderBottom: "1px solid #e0e0e0" }}>
              Saved For Later ({savedForLater.length})
            </h3>
            {savedForLater.map((item) => {
              const r = itemRatings[item.id] || { rating: "4.2", count: 50000 };
              return (
                <div key={item.id} style={{ borderBottom: "1px solid #f0f0f0", paddingBottom: "16px", marginBottom: "16px" }}>
                  <div style={{ display: "flex", gap: "14px" }}>
                    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", minWidth: "75px" }}>
                      <img
                        src={resolvePath(item.mainimg)}
                        alt={item.name}
                        style={{ width: "75px", height: "75px", objectFit: "contain" }}
                      />
                    </div>
                    <div style={{ flex: 1 }}>
                      <p style={{ margin: 0, fontSize: "15px", fontWeight: "500", color: "#212121", lineHeight: 1.4 }}>
                        {item.name}
                      </p>
                      <Box sx={{ display: "flex", alignItems: "center", mt: 0.5, fontSize: 12 }}>
                        <Rating
                          value={parseFloat(r.rating)}
                          precision={0.1}
                          readOnly
                          size="small"
                          sx={{
                            "& .MuiRating-iconFilled": { color: "#008c00" },
                            "& .MuiRating-iconEmpty": { color: "#bdbdbd" },
                          }}
                        />
                        <span style={{ marginLeft: 4, color: "#878787", fontSize: "12px" }}>
                          {r.rating} ({r.count.toLocaleString()})
                        </span>
                        <img
                          src={resolvePath("/img/wow.png")}
                          alt="Assured"
                          style={{ height: "16px", marginLeft: "6px" }}
                        />
                      </Box>
                      <div style={{ display: "flex", alignItems: "baseline", gap: "8px", marginTop: "6px" }}>
                        {isBot ? (
                          <span style={{ fontWeight: "600", fontSize: "16px" }}>{item.total}</span>
                        ) : (
                          <>
                            <span style={{ color: "#388e3c", fontWeight: "700", fontSize: "16px" }}>
                              <i className="fa-solid fa-arrow-down" style={{ fontSize: "12px", marginRight: "2px" }}></i>{item.dis} Off
                            </span>
                            <span style={{ textDecoration: "line-through", color: "#878787", fontSize: "14px" }}>
                              {item.total}
                            </span>
                            <span style={{ fontWeight: "700", fontSize: "18px", color: "#212121" }}>
                              ₹{String(item.disprice).replace(/[₹]/g, "")}
                            </span>
                          </>
                        )}
                      </div>
                    </div>
                  </div>
                  <div style={{ display: "flex", marginTop: "14px", paddingTop: "10px" }}>
                    <button onClick={() => removeSavedItem(item.id)} style={{ flex: 1, background: "none", border: "none", borderRight: "1px solid #f0f0f0", cursor: "pointer", fontSize: "13px", color: "#212121", padding: "4px 0", display: "flex", alignItems: "center", justifyContent: "center", gap: "5px" }}>
                      <i className="fa-regular fa-trash-can" style={{ fontSize: "13px" }}></i> Remove
                    </button>
                    <button onClick={() => moveToCart(item.id)} style={{ flex: 1, background: "none", border: "none", cursor: "pointer", fontSize: "13px", color: "#212121", padding: "4px 0", display: "flex", alignItems: "center", justifyContent: "center", gap: "5px" }}>
                      <i className="fa-solid fa-cart-shopping" style={{ fontSize: "13px" }}></i> Move to Cart
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Price Details Card */}
        <div style={{ background: "#fff", padding: "16px", marginBottom: "8px" }}>
          <h3 style={{ fontSize: "16px", fontWeight: "600", margin: "0 0 14px 0", paddingBottom: "12px", borderBottom: "1px solid #e0e0e0", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span>Price Details</span>
            <i className="fa-solid fa-chevron-up" style={{ fontSize: "12px", color: "#878787" }}></i>
          </h3>

          <div style={{ display: "flex", justifyContent: "space-between", padding: "6px 0", fontSize: "14px", color: "#212121" }}>
            <span>Price ({cart.length} {cart.length === 1 ? "item" : "items"})</span>
            <span>₹{totalMRP.toLocaleString("en-IN")}</span>
          </div>

          {!isBot && (
            <div style={{ display: "flex", justifyContent: "space-between", padding: "6px 0", fontSize: "14px" }}>
              <span style={{ color: "#388e3c" }}>Discount</span>
              <span style={{ color: "#388e3c" }}>- ₹{totalDiscount.toLocaleString("en-IN")}</span>
            </div>
          )}

          <div style={{ display: "flex", justifyContent: "space-between", padding: "6px 0", fontSize: "14px", color: "#212121" }}>
            <span>Platform Fee</span>
            <span>₹0</span>
          </div>

          <div style={{ display: "flex", justifyContent: "space-between", padding: "12px 0 6px", fontSize: "16px", fontWeight: "700", borderTop: "1px dashed #e0e0e0", marginTop: "6px", color: "#212121" }}>
            <span>Total Amount</span>
            <span>₹{totalPrice.toLocaleString("en-IN")}</span>
          </div>

          {!isBot && totalDiscount > 0 && (
            <p style={{ color: "#388e3c", fontSize: "14px", fontWeight: "500", margin: "10px 0 0 0" }}>
              You will save ₹{totalDiscount.toLocaleString("en-IN")} on this order
            </p>
          )}
        </div>

        {/* Safe payment section */}
        <div style={{ background: "#fff", padding: "20px 16px", display: "flex", alignItems: "flex-start", gap: "12px" }}>
          <i className="fa-solid fa-shield-halved" style={{ fontSize: "28px", color: "#878787", marginTop: "2px" }}></i>
          <p style={{ margin: 0, fontSize: "13px", color: "#212121", lineHeight: 1.5 }}>
            <strong>Safe and secure payments.</strong> Easy returns. 100% Authentic products.
          </p>
        </div>
      </div>

      {/* Footer bar */}
      <div className="footer-btn">
        <div className="b-btn" style={{ border: "none", display: "flex", flexDirection: "column", alignItems: "flex-start", justifyContent: "center", padding: "8px 16px" }}>
          <span style={{ fontSize: "12px", color: "#878787", textDecoration: "line-through" }}>
            {totalMRP.toLocaleString("en-IN")}
          </span>
          <div style={{ display: "flex", alignItems: "center", gap: "4px" }}>
            <span style={{ fontSize: "18px", fontWeight: "700", color: "#212121" }}>₹{totalPrice.toLocaleString("en-IN")}</span>
            <i className="fa-solid fa-circle-info" style={{ fontSize: "12px", color: "#878787" }}></i>
          </div>
        </div>
        <button
          className="b-btn"
          style={{
            background: "#ffc107",
            border: "none",
            fontSize: "16px",
            fontWeight: "600",
            padding: "14px 24px",
            borderRadius: "4px",
            color: "#212121",
            cursor: "pointer",
          }}
          onClick={handleCheckout}
        >
          Place order
        </button>
      </div>
    </div>
  );
}

export default CartPage;
